import Advance from '@civ-clone/core-science/Advance';

export class Railroad extends Advance {
  /**
   * A save records this class by name, and the name is ambiguous:
   * `Railroad` is also a `TileImprovement` in
   * `base-tile-improvement-railroad`.
   *
   * The collision only surfaced once `AvailableTileImprovementRegistry`
   * existed — before that the tile improvement's class was in no registry,
   * so nothing ever tried to register both. Fixing one gap exposed the
   * next, which is the usual shape of this.
   *
   * Internal references keep the short name: this is the persisted
   * identity, not the export.
   */
  static readonly type = 'RailroadAdvance';
}

export default Railroad;
